"use client";

// Generated by `yarn locale-clients` (scripts/localeClients.ts): do not edit.
import type { ComponentType, ReactNode } from "react";
import dynamic from "next/dynamic";
import type { PrefixedLocale } from "~~/i18n/locales";

type Root = ComponentType<{ children: ReactNode }>;

// One import() per language, so each language's client root and strings are a chunk of their own that a page loads
// only when it renders that language. Static imports of every root would put them all in the shared layout's bundle.
// Server-rendered as usual: next/dynamic preloads the chunk of the root a page renders.
const ROOTS: Record<PrefixedLocale, Root> = {
  cs: dynamic(() => import("~~/i18n/client/cs").then(module => module.LocaleRoot)),
  es: dynamic(() => import("~~/i18n/client/es").then(module => module.LocaleRoot)),
  hi: dynamic(() => import("~~/i18n/client/hi").then(module => module.LocaleRoot)),
  de: dynamic(() => import("~~/i18n/client/de").then(module => module.LocaleRoot)),
  vi: dynamic(() => import("~~/i18n/client/vi").then(module => module.LocaleRoot)),
  fr: dynamic(() => import("~~/i18n/client/fr").then(module => module.LocaleRoot)),
  pt: dynamic(() => import("~~/i18n/client/pt").then(module => module.LocaleRoot)),
  it: dynamic(() => import("~~/i18n/client/it").then(module => module.LocaleRoot)),
  pl: dynamic(() => import("~~/i18n/client/pl").then(module => module.LocaleRoot)),
  tr: dynamic(() => import("~~/i18n/client/tr").then(module => module.LocaleRoot)),
  id: dynamic(() => import("~~/i18n/client/id").then(module => module.LocaleRoot)),
  nl: dynamic(() => import("~~/i18n/client/nl").then(module => module.LocaleRoot)),
  ro: dynamic(() => import("~~/i18n/client/ro").then(module => module.LocaleRoot)),
  hu: dynamic(() => import("~~/i18n/client/hu").then(module => module.LocaleRoot)),
  hr: dynamic(() => import("~~/i18n/client/hr").then(module => module.LocaleRoot)),
  sl: dynamic(() => import("~~/i18n/client/sl").then(module => module.LocaleRoot)),
  sr: dynamic(() => import("~~/i18n/client/sr").then(module => module.LocaleRoot)),
  sv: dynamic(() => import("~~/i18n/client/sv").then(module => module.LocaleRoot)),
  da: dynamic(() => import("~~/i18n/client/da").then(module => module.LocaleRoot)),
  nb: dynamic(() => import("~~/i18n/client/nb").then(module => module.LocaleRoot)),
  fil: dynamic(() => import("~~/i18n/client/fil").then(module => module.LocaleRoot)),
  bg: dynamic(() => import("~~/i18n/client/bg").then(module => module.LocaleRoot)),
  ru: dynamic(() => import("~~/i18n/client/ru").then(module => module.LocaleRoot)),
  uk: dynamic(() => import("~~/i18n/client/uk").then(module => module.LocaleRoot)),
  el: dynamic(() => import("~~/i18n/client/el").then(module => module.LocaleRoot)),
};

/** The client root of a prefixed language (app/(intl)/[lang]/layout.tsx). English mounts its own root directly. */
export const PrefixedLocaleRoot = ({ locale, children }: { locale: PrefixedLocale; children: ReactNode }) => {
  const LocaleRoot = ROOTS[locale];
  return <LocaleRoot>{children}</LocaleRoot>;
};
